INSERT OR IGNORE INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) SELECT id, 'projectile-intro', 'โพรเจกไทล์: ยิงวัตถุเฉียงขึ้น', 'วัตถุที่ถูกยิงเฉียงขึ้นจะเคลื่อนที่เป็นเส้นโค้งพาราโบลา แนวราบความเร็วคงที่ แนวดิ่งมีความเร่ง g ลองปรับมุมและความเร็วต้นแล้วดูผล', 'senior', 1, 'published' FROM chapters WHERE slug = 'projectile';
INSERT OR IGNORE INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) SELECT id, 'coulomb-law', 'แรงไฟฟ้าและกฎของคูลอมบ์', 'แรงระหว่างประจุไฟฟ้าสองจุดแปรผันตามผลคูณของประจุ และแปรผกผันกับกำลังสองของระยะห่าง ลองเปลี่ยนประจุและระยะห่างแล้วดูแรงที่เปลี่ยนไป', 'senior', 1, 'published' FROM chapters WHERE slug = 'electrostatics';
INSERT OR IGNORE INTO lessons (chapter_id, slug, title, summary, level, sort_order, status) SELECT id, 'light-reflection', 'สมบัติของแสงและการสะท้อน', 'เมื่อแสงตกกระทบผิวเรียบ มุมตกกระทบเท่ากับมุมสะท้อน โดยวัดมุมจากเส้นแนวฉากเสมอ ลองปรับมุมของรังสีแล้วสังเกตรังสีสะท้อน', 'senior', 1, 'published' FROM chapters WHERE slug = 'reflection-refraction';
