INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order, is_active) SELECT l.id, 'youtube', 'https://www.youtube.com/watch?v=fNc40hNzhVA', 'fNc40hNzhVA', 'ฟิสิกส์ ม.ปลาย ในคลิปเดียว (20 บท)', 'Physics Blueprint (พี่ตั้ว)', NULL, 1, 1 FROM lessons l WHERE l.slug = 'projectile-intro' AND NOT EXISTS (SELECT 1 FROM videos x WHERE x.lesson_id = l.id AND x.url = 'https://www.youtube.com/watch?v=fNc40hNzhVA');
INSERT INTO animations (lesson_id, engine, title, config_json) SELECT l.id, 'projectile', 'จำลองการยิงวัตถุ', '{"angle": {"min": 10, "max": 80, "default": 45}, "speed": {"min": 10, "max": 40, "default": 25}}' FROM lessons l WHERE l.slug = 'projectile-intro' AND NOT EXISTS (SELECT 1 FROM animations x WHERE x.lesson_id = l.id);
INSERT INTO games (lesson_id, template, title, config_json) SELECT l.id, 'aim-and-shoot', 'ยิงให้ตรงเป้า', '{"targetDistance": [40, 120], "tolerance": 5}' FROM lessons l WHERE l.slug = 'projectile-intro' AND NOT EXISTS (SELECT 1 FROM games x WHERE x.lesson_id = l.id);
INSERT INTO quizzes (lesson_id, title, pass_score) SELECT l.id, 'แบบทดสอบ โพรเจกไทล์', 60 FROM lessons l WHERE l.slug = 'projectile-intro' AND NOT EXISTS (SELECT 1 FROM quizzes x WHERE x.lesson_id = l.id);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) SELECT z.id, 'choice', 'ถ้าความเร็วต้นเท่ากัน และไม่คิดแรงต้านอากาศ มุมยิงใดทำให้ระยะทางในแนวราบไกลที่สุด', '["30 องศา", "45 องศา", "60 องศา", "90 องศา"]', '1', 'ระยะทางในแนวราบ R = v² sin 2θ / g และ sin 2θ มีค่ามากที่สุดเมื่อ 2θ = 90 องศา คือ θ = 45 องศา', 1 FROM quizzes z JOIN lessons l ON l.id = z.lesson_id WHERE l.slug = 'projectile-intro' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.quiz_id = z.id AND x.body = 'ถ้าความเร็วต้นเท่ากัน และไม่คิดแรงต้านอากาศ มุมยิงใดทำให้ระยะทางในแนวราบไกลที่สุด');
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) SELECT z.id, 'choice', 'ที่จุดสูงสุดของวิถีโพรเจกไทล์ (ไม่คิดแรงต้านอากาศ) ข้อใดถูกต้อง', '["ความเร็วเป็นศูนย์", "ความเร็วในแนวดิ่งเป็นศูนย์ แต่ความเร็วในแนวราบยังเท่าเดิม", "ความเร่งเป็นศูนย์", "ความเร็วในแนวราบเป็นศูนย์"]', '1', 'แรงโน้มถ่วงกระทำในแนวดิ่งเท่านั้น ที่จุดสูงสุดความเร็วแนวดิ่ง vy = 0 แต่ความเร็วแนวราบ vx คงที่ และความเร่ง g ยังคงอยู่', 2 FROM quizzes z JOIN lessons l ON l.id = z.lesson_id WHERE l.slug = 'projectile-intro' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.quiz_id = z.id AND x.body = 'ที่จุดสูงสุดของวิถีโพรเจกไทล์ (ไม่คิดแรงต้านอากาศ) ข้อใดถูกต้อง');
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) SELECT z.id, 'number', 'ยิงวัตถุด้วยความเร็วต้น 20 เมตร/วินาที ทำมุม 30 องศากับแนวราบ (กำหนด g = 10 เมตร/วินาที²) วัตถุลอยอยู่ในอากาศนานกี่วินาที', NULL, '{"value": 2, "tolerance": 0.05}', 'T = 2·v·sin θ / g = 2 × 20 × sin 30° / 10 = 2 × 20 × 0.5 / 10 = 2 วินาที', 3 FROM quizzes z JOIN lessons l ON l.id = z.lesson_id WHERE l.slug = 'projectile-intro' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.quiz_id = z.id AND x.body = 'ยิงวัตถุด้วยความเร็วต้น 20 เมตร/วินาที ทำมุม 30 องศากับแนวราบ (กำหนด g = 10 เมตร/วินาที²) วัตถุลอยอยู่ในอากาศนานกี่วินาที');
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order, is_active) SELECT l.id, 'youtube', 'https://www.youtube.com/watch?v=u0nVk4FLAz8', 'u0nVk4FLAz8', 'ฟิสิกส์ ม.5 บทที่ 13 ไฟฟ้าสถิต ep.2 (แรงไฟฟ้าและกฎของคูลอมบ์)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1, 1 FROM lessons l WHERE l.slug = 'coulomb-law' AND NOT EXISTS (SELECT 1 FROM videos x WHERE x.lesson_id = l.id AND x.url = 'https://www.youtube.com/watch?v=u0nVk4FLAz8');
INSERT INTO animations (lesson_id, engine, title, config_json) SELECT l.id, 'coulomb', 'จำลองแรงระหว่างประจุ', '{"q1": {"min": 1, "max": 10, "default": 2}, "q2": {"min": 1, "max": 10, "default": 3}, "r": {"min": 0.1, "max": 1.0, "default": 0.3}}' FROM lessons l WHERE l.slug = 'coulomb-law' AND NOT EXISTS (SELECT 1 FROM animations x WHERE x.lesson_id = l.id);
INSERT INTO quizzes (lesson_id, title, pass_score) SELECT l.id, 'แบบทดสอบ กฎของคูลอมบ์', 60 FROM lessons l WHERE l.slug = 'coulomb-law' AND NOT EXISTS (SELECT 1 FROM quizzes x WHERE x.lesson_id = l.id);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) SELECT z.id, 'choice', 'ถ้าระยะห่างระหว่างประจุไฟฟ้าสองจุดเพิ่มเป็น 2 เท่า แรงไฟฟ้าระหว่างประจุจะเป็นกี่เท่าของเดิม', '["2 เท่า", "1/2 เท่า", "1/4 เท่า", "4 เท่า"]', '2', 'F แปรผกผันกับ r² เมื่อ r เพิ่มเป็น 2 เท่า F จะเป็น 1/2² = 1/4 เท่าของเดิม', 1 FROM quizzes z JOIN lessons l ON l.id = z.lesson_id WHERE l.slug = 'coulomb-law' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.quiz_id = z.id AND x.body = 'ถ้าระยะห่างระหว่างประจุไฟฟ้าสองจุดเพิ่มเป็น 2 เท่า แรงไฟฟ้าระหว่างประจุจะเป็นกี่เท่าของเดิม');
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) SELECT z.id, 'choice', 'ถ้าประจุตัวหนึ่งเพิ่มเป็น 3 เท่า โดยประจุอีกตัวและระยะห่างเท่าเดิม แรงไฟฟ้าจะเป็นกี่เท่าของเดิม', '["1/3 เท่า", "3 เท่า", "6 เท่า", "9 เท่า"]', '1', 'F แปรผันตรงกับผลคูณ q1·q2 เมื่อ q1 เพิ่มเป็น 3 เท่า F จึงเพิ่มเป็น 3 เท่า', 2 FROM quizzes z JOIN lessons l ON l.id = z.lesson_id WHERE l.slug = 'coulomb-law' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.quiz_id = z.id AND x.body = 'ถ้าประจุตัวหนึ่งเพิ่มเป็น 3 เท่า โดยประจุอีกตัวและระยะห่างเท่าเดิม แรงไฟฟ้าจะเป็นกี่เท่าของเดิม');
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) SELECT z.id, 'number', 'ประจุ 2 ไมโครคูลอมบ์ และ 3 ไมโครคูลอมบ์ วางห่างกัน 0.3 เมตร (กำหนด k = 9×10⁹ นิวตัน·เมตร²/คูลอมบ์²) แรงไฟฟ้ามีขนาดกี่นิวตัน', NULL, '{"value": 0.6, "tolerance": 0.01}', 'F = k·q1·q2 / r² = (9×10⁹ × 2×10⁻⁶ × 3×10⁻⁶) / 0.3² = 0.054 / 0.09 = 0.6 นิวตัน', 3 FROM quizzes z JOIN lessons l ON l.id = z.lesson_id WHERE l.slug = 'coulomb-law' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.quiz_id = z.id AND x.body = 'ประจุ 2 ไมโครคูลอมบ์ และ 3 ไมโครคูลอมบ์ วางห่างกัน 0.3 เมตร (กำหนด k = 9×10⁹ นิวตัน·เมตร²/คูลอมบ์²) แรงไฟฟ้ามีขนาดกี่นิวตัน');
INSERT INTO videos (lesson_id, provider, url, youtube_id, title, channel_name, channel_url, sort_order, is_active) SELECT l.id, 'youtube', 'https://www.youtube.com/watch?v=OWvMKjP-d1s', 'OWvMKjP-d1s', 'ฟิสิกส์ ม.5 บทที่ 11 แสงเชิงรังสี ep.1 (สมบัติของแสง การสะท้อนของแสง)', 'ฟิสิกส์ by ครูโน้ต', 'https://www.youtube.com/@notesapichat', 1, 1 FROM lessons l WHERE l.slug = 'light-reflection' AND NOT EXISTS (SELECT 1 FROM videos x WHERE x.lesson_id = l.id AND x.url = 'https://www.youtube.com/watch?v=OWvMKjP-d1s');
INSERT INTO animations (lesson_id, engine, title, config_json) SELECT l.id, 'reflection', 'จำลองการสะท้อนของแสง', '{"angle": {"min": 0, "max": 80, "default": 40}}' FROM lessons l WHERE l.slug = 'light-reflection' AND NOT EXISTS (SELECT 1 FROM animations x WHERE x.lesson_id = l.id);
INSERT INTO quizzes (lesson_id, title, pass_score) SELECT l.id, 'แบบทดสอบ การสะท้อนของแสง', 60 FROM lessons l WHERE l.slug = 'light-reflection' AND NOT EXISTS (SELECT 1 FROM quizzes x WHERE x.lesson_id = l.id);
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) SELECT z.id, 'number', 'รังสีแสงตกกระทบกระจกเงาราบ โดยทำมุม 40 องศากับเส้นแนวฉาก มุมสะท้อนมีกี่องศา', NULL, '{"value": 40, "tolerance": 0.5}', 'กฎการสะท้อน: มุมตกกระทบเท่ากับมุมสะท้อน (วัดจากเส้นแนวฉากทั้งคู่) จึงเป็น 40 องศา', 1 FROM quizzes z JOIN lessons l ON l.id = z.lesson_id WHERE l.slug = 'light-reflection' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.quiz_id = z.id AND x.body = 'รังสีแสงตกกระทบกระจกเงาราบ โดยทำมุม 40 องศากับเส้นแนวฉาก มุมสะท้อนมีกี่องศา');
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) SELECT z.id, 'choice', 'ข้อใดเป็นกฎการสะท้อนของแสงที่ถูกต้อง', '["มุมตกกระทบเท่ากับมุมสะท้อน", "มุมตกกระทบมากกว่ามุมสะท้อนเสมอ", "รังสีตกกระทบ รังสีสะท้อน และเส้นแนวฉากอยู่คนละระนาบ", "มุมสะท้อนเท่ากับ 90 องศาเสมอ"]', '0', 'กฎการสะท้อนมี 2 ข้อ คือ มุมตกกระทบเท่ากับมุมสะท้อน และรังสีตกกระทบ รังสีสะท้อน กับเส้นแนวฉากอยู่ในระนาบเดียวกัน', 2 FROM quizzes z JOIN lessons l ON l.id = z.lesson_id WHERE l.slug = 'light-reflection' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.quiz_id = z.id AND x.body = 'ข้อใดเป็นกฎการสะท้อนของแสงที่ถูกต้อง');
INSERT INTO questions (quiz_id, type, body, choices_json, answer_json, explanation, sort_order) SELECT z.id, 'number', 'รังสีแสงตกกระทบกระจกเงาราบ โดยทำมุม 30 องศากับผิวกระจก (ไม่ใช่กับเส้นแนวฉาก) มุมสะท้อนที่วัดจากเส้นแนวฉากมีกี่องศา', NULL, '{"value": 60, "tolerance": 0.5}', 'มุมตกกระทบวัดจากเส้นแนวฉาก = 90 − 30 = 60 องศา ดังนั้นมุมสะท้อนเป็น 60 องศา', 3 FROM quizzes z JOIN lessons l ON l.id = z.lesson_id WHERE l.slug = 'light-reflection' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.quiz_id = z.id AND x.body = 'รังสีแสงตกกระทบกระจกเงาราบ โดยทำมุม 30 องศากับผิวกระจก (ไม่ใช่กับเส้นแนวฉาก) มุมสะท้อนที่วัดจากเส้นแนวฉากมีกี่องศา');
